<script setup>
import InputError from '@/Components/InputError.vue'; import { Link,useForm } from '@inertiajs/vue3'; const props=defineProps({customer:{type:Object,default:null},products:{type:Array,required:true},assignees:{type:Array,required:true}}); const form=useForm({type:props.customer?.type||'organization',name:props.customer?.name||'',email:props.customer?.email||'',phone:props.customer?.phone||'',website:props.customer?.website||'',tax_id:props.customer?.tax_id||'',billing_address:props.customer?.billing_address||'',city:props.customer?.city||'',state:props.customer?.state||'',country:props.customer?.country||'NG',status:props.customer?.status||'lead',source:props.customer?.source||'',assigned_to:props.customer?.assigned_to||'',metadata:props.customer?.metadata||{},product_ids:(props.customer?.products||[]).map(product=>product.id),contacts:(props.customer?.contacts||[]).map(({name,job_title,email,phone,is_primary})=>({name,job_title:job_title||'',email:email||'',phone:phone||'',is_primary})),addresses:(props.customer?.addresses||[]).map(({type,label,address_line_1,address_line_2,city,state,postal_code,country,is_primary})=>({type,label:label||'',address_line_1,address_line_2:address_line_2||'',city:city||'',state:state||'',postal_code:postal_code||'',country,is_primary}))}); const submit=()=>props.customer?form.put(route('admin.customers.update',props.customer.id)):form.post(route('admin.customers.store'));
</script>
<template><form class="form-card" @submit.prevent="submit"><div class="form-grid"><label>Customer type<select v-model="form.type"><option value="organization">Organization</option><option value="individual">Individual</option></select><InputError :message="form.errors.type"/></label><label>Name<input v-model="form.name" required/><InputError :message="form.errors.name"/></label><label>Email<input v-model="form.email" type="email"/><InputError :message="form.errors.email"/></label><label>Phone<input v-model="form.phone"/><InputError :message="form.errors.phone"/></label><label>Website<input v-model="form.website" type="url"/><InputError :message="form.errors.website"/></label><label>Tax ID<input v-model="form.tax_id"/><InputError :message="form.errors.tax_id"/></label><label>Status<select v-model="form.status"><option value="lead">Lead</option><option value="prospect">Prospect</option><option value="active">Active</option><option value="suspended">Suspended</option><option value="inactive">Inactive</option></select><InputError :message="form.errors.status"/></label><label>Source<input v-model="form.source" placeholder="Referral, website, campaign"/><InputError :message="form.errors.source"/></label><label>Assigned to<select v-model="form.assigned_to"><option value="">Unassigned</option><option v-for="user in assignees" :key="user.id" :value="user.id">{{ user.name }}</option></select><InputError :message="form.errors.assigned_to"/></label><label>Country code<input v-model="form.country" maxlength="2" class="uppercase"/><InputError :message="form.errors.country"/></label><label>City<input v-model="form.city"/><InputError :message="form.errors.city"/></label><label>State<input v-model="form.state"/><InputError :message="form.errors.state"/></label></div><label>Billing address<textarea v-model="form.billing_address" rows="3"/><InputError :message="form.errors.billing_address"/></label>
<section class="space-y-4 border-t border-slate-200 pt-6"><div><h2 class="text-xl font-bold">KernelBridge products</h2><p class="text-sm text-slate-500">Select every product used by or proposed to this customer.</p></div><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><label v-for="product in products" :key="product.id" class="flex items-center gap-3 rounded-xl border border-slate-200 p-4"><input v-model="form.product_ids" type="checkbox" :value="product.id" class="!mt-0"/><span><strong class="block">{{ product.name }}</strong><small class="text-slate-500">{{ product.code }}</small></span></label></div><InputError :message="form.errors.product_ids"/></section>
<section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Contacts</h2><p class="text-sm text-slate-500">Decision makers and operational contacts.</p></div><button type="button" class="form-secondary-button" @click="form.contacts.push({name:'',job_title:'',email:'',phone:'',is_primary:false})">Add contact</button></div><div v-for="(contact,index) in form.contacts" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Name<input v-model="contact.name" required/></label><label>Job title<input v-model="contact.job_title"/></label><label>Email<input v-model="contact.email" type="email"/></label><label>Phone<input v-model="contact.phone"/></label></div><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="contact.is_primary" type="checkbox" class="!mt-0"/>Primary contact</label><button type="button" class="text-sm font-bold text-red-600" @click="form.contacts.splice(index,1)">Remove</button></div><InputError :message="form.errors[`contacts.${index}.name`]"/></div></section>
<section class="space-y-4 border-t border-slate-200 pt-6"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Addresses</h2><p class="text-sm text-slate-500">Billing, shipping, and office locations.</p></div><button type="button" class="form-secondary-button" @click="form.addresses.push({type:'billing',label:'',address_line_1:'',address_line_2:'',city:'',state:'',postal_code:'',country:form.country||'NG',is_primary:false})">Add address</button></div><div v-for="(address,index) in form.addresses" :key="index" class="rounded-xl border border-slate-200 p-4"><div class="form-grid"><label>Type<select v-model="address.type"><option value="billing">Billing</option><option value="shipping">Shipping</option><option value="office">Office</option><option value="other">Other</option></select></label><label>Label<input v-model="address.label"/></label><label>Address line 1<input v-model="address.address_line_1" required/></label><label>Address line 2<input v-model="address.address_line_2"/></label><label>City<input v-model="address.city"/></label><label>State<input v-model="address.state"/></label><label>Postal code<input v-model="address.postal_code"/></label><label>Country code<input v-model="address.country" maxlength="2" required class="uppercase"/></label></div><div class="flex justify-between"><label class="flex items-center gap-2"><input v-model="address.is_primary" type="checkbox" class="!mt-0"/>Primary address</label><button type="button" class="text-sm font-bold text-red-600" @click="form.addresses.splice(index,1)">Remove</button></div><InputError :message="form.errors[`addresses.${index}.address_line_1`]"/></div></section>
<div class="flex gap-3"><button class="form-button" :disabled="form.processing">{{ customer?'Save customer':'Create customer' }}</button><Link :href="route('admin.customers.index')" class="rounded-xl border border-slate-300 px-6 py-3.5 font-bold">Cancel</Link></div></form></template>
